const protectedErrorText=(error:unknown)=>error instanceof ApiError&&error.status===404?'That report is unavailable or you no longer have access.':error instanceof ApiError&&error.code==='PROVIDER_UNAVAILABLE'?'The sign-in provider is unavailable. Please try again later.':error instanceof ApiError&&error.code==='OIDC_RESPONSE_INVALID'?'Sign-in could not be validated. Please try again.':error instanceof ApiError&&error.status===401?'Your APBRA session has expired. Sign in again to continue.':error instanceof ApiError&&error.code==='STALE_VERSION'?'This report changed in another session. Reload it before saving your changes.':error instanceof ApiError&&error.code==='LAST_OWNER_REQUIRED'?'A company must retain an active Company Owner. This owner cannot be deactivated or changed here.':error instanceof Error?error.message:'The request could not be completed.';
export const protectedErrorMessage=(error:unknown)=>{const message=protectedErrorText(error);if(!(error instanceof ApiError)||typeof error.support_reference!=='string'||!/^([0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12})$/i.test(error.support_reference))return message;return `${message} Support reference: ${error.support_reference}.${error.recorded===false?' Diagnostic history is unavailable.':error.recorded===true?' Recorded in error history.':''}`};
export const companyCreationErrorMessage=(error:unknown)=>error instanceof ApiError&&error.status===401?'Your APBRA session has expired. Sign in again to continue.':error instanceof ApiError&&error.code==='COMPANY_NAME_INVALID'?'Enter a company name of up to 200 characters without control characters.':error instanceof ApiError&&error.code==='COMPANY_CREATION_NOT_AVAILABLE'?'Your company access changed. Review your current company or invitation state.':error instanceof ApiError&&error.code==='IDEMPOTENCY_CONFLICT'?'This creation attempt was already used with a different name. Review the name before trying again.':'Company creation could not be completed. Please try again.';
class ProfileRefreshError extends Error{}
export const profileErrorMessage=(error:unknown)=>error instanceof ProfileRefreshError?'Your profile was saved, but this page could not refresh your name. Reload the page before making another change.':error instanceof ApiError&&error.status===401?'Your APBRA session has expired. Sign in again to continue.':error instanceof ApiError&&error.code==='PROFILE_INVALID'?'Enter a display name of up to 200 characters without control characters.':!(error instanceof ApiError)||error.status>=500?'The save response could not be confirmed. Your name may have changed. Reload the page to check it before trying again.':'Your profile could not be saved. Please try again.';
