export function SignedOut({message,providers}:{message?:string;providers?:IdentityProviders}){
  const [mode,setMode]=useState<'signin'|'signup'>('signin');
  const [nativeBusy,setNativeBusy]=useState(false),[nativeStep,setNativeStep]=useState<'signin'|'signup'|'recover'|'verify'|'reset'>('signin');
  const signup=nativeStep==='signup',options=providers?.items??[];
  const handleStepChanged=useCallback((step:'signin'|'signup'|'recover'|'verify'|'reset')=>{setNativeStep(step);if(step==='signin'||step==='signup')setMode(step)},[]);
  const heading=nativeStep==='verify'?'Verify your email':nativeStep==='reset'?'Set a new password':nativeStep==='recover'?'Recover your account':signup?'Create your account':'Sign in to APBRA';
  useEffect(()=>{document.title=heading+' · APBRA'},[heading]);
  // Native account sessions are separate from existing provider memberships.
  return <main className="auth-page auth-entry-page"><div className="auth-shell"><section className="auth-story" aria-label="APBRA reporting workspace"><div className="auth-brand"><span className="brand-mark" aria-hidden="true">A</span><strong>APBRA</strong></div><div className="auth-story-body"><span className="eyebrow">A clearer way to report</span><p className="auth-story-headline">From a business question to a report you can review.</p><p>Bring your goals, supporting information and AI-generated reports together in one private workspace.</p><div className="auth-story-steps"><span><strong>01</strong> Describe your goal</span><span><strong>02</strong> Refine with AI</span><span><strong>03</strong> Review your report</span></div></div><div className="auth-story-footer">Your goals. Your workspace. Your reports.</div></section><section className="auth-card" aria-labelledby="account-access-title">{!['recover','verify','reset'].includes(nativeStep)&&<nav className="auth-mode" aria-label="Account access"><button type="button" aria-pressed={!signup} disabled={nativeBusy} onClick={()=>{setMode('signin')}}>Sign in</button><button type="button" aria-pressed={signup} disabled={nativeBusy} onClick={()=>{setMode('signup')}}>Create account</button></nav>}<p className="eyebrow">{signup?'Get started with APBRA':'Welcome back'}</p><h1 id="account-access-title">{heading}</h1><p className="auth-intro">{nativeStep==='verify'?'Confirm ownership of your email address.':nativeStep==='reset'?'Choose a new password for this account.':nativeStep==='recover'?'Request a secure password reset link.':signup?'Create your account with your email address.':'Access your workspace and pick up where you left off.'}</p>{message&&<p role="alert" className="auth-message">{message}</p>}<PasswordAccount mode={mode} onBusyChanged={setNativeBusy} onStepChanged={handleStepChanged}/>{options.length>0?<details className="auth-existing-access"><summary>Other sign-in options</summary><p>Sign in to an existing workspace.</p>{options.map(provider=><a key={provider.profile_id} href={authApi.loginUrl({profileId:provider.profile_id})}>{options.length===1?'Continue to your workspace':`Continue with ${provider.display_label}`}</a>)}</details>:null}</section></div></main>
}

